    val timeZone: String,
)

@Serializable(with = WorkspaceUpdateEvent.Serializer::class)
sealed interface WorkspaceUpdateEvent {
    @Serializable
    data class ThreadChanged(
        @EncodeDefault val v: Long = 1L,
        @EncodeDefault val type: String = "thread.changed",
        val threadId: String,
    ) : WorkspaceUpdateEvent

    @Serializable
    data class ConversationThreadChanged(
        @EncodeDefault val v: Long = 1L,
        @EncodeDefault val type: String = "conversation.thread_changed",
        val conversationId: String,
        val threadId: String,
    ) : WorkspaceUpdateEvent

    @Serializable
    data class Reset(
        @EncodeDefault val v: Long = 1L,
        @EncodeDefault val type: String = "reset",
    ) : WorkspaceUpdateEvent

    /** A kind from a newer server than this app knows, by its `type`, which can't be sent. */
    data class Unknown(val tag: String) : WorkspaceUpdateEvent

    object Serializer : JsonUnionSerializer<WorkspaceUpdateEvent>("ai.sugabots.api.WorkspaceUpdateEvent") {
        override fun decode(element: JsonElement, json: Json): WorkspaceUpdateEvent =
            when (val tag = tagOf(element, "type")) {
                "thread.changed" -> json.decodeFromJsonElement<ThreadChanged>(element)
                "conversation.thread_changed" -> json.decodeFromJsonElement<ConversationThreadChanged>(element)
                "reset" -> json.decodeFromJsonElement<Reset>(element)
                else -> Unknown(tag)
            }

        override fun encode(value: WorkspaceUpdateEvent, json: Json): JsonElement =
            when (value) {
                is ThreadChanged -> json.encodeToJsonElement<ThreadChanged>(value)
                is ConversationThreadChanged -> json.encodeToJsonElement<ConversationThreadChanged>(value)
                is Reset -> json.encodeToJsonElement<Reset>(value)
                is Unknown -> throw SerializationException("A kind this app doesn't know can't be sent.")
            }
    }
}

@Serializable
