/**
 * The API's routes, grouped as the web's client groups them: `api.threads.get(...)`
 * there is `client.threads.get(...)` here.
 */
class ApiClient(transport: ApiTransport, json: Json = ApiJson) : ApiCaller(transport, json) {
    /** The `agents` routes, as `api.agents` in the web's client. */
    val agents: AgentsRoutes = AgentsRoutes(this)

    /** The `artifacts` routes, as `api.artifacts` in the web's client. */
    val artifacts: ArtifactsRoutes = ArtifactsRoutes(this)

    /** The `chats` routes, as `api.chats` in the web's client. */
    val chats: ChatsRoutes = ChatsRoutes(this)

    /** The `connections` routes, as `api.connections` in the web's client. */
    val connections: ConnectionsRoutes = ConnectionsRoutes(this)

    /** The `events` routes, as `api.events` in the web's client. */
    val events: EventsRoutes = EventsRoutes(this)

    /** The `gitHubConnections` routes, as `api.gitHubConnections` in the web's client. */
    val gitHubConnections: GitHubConnectionsRoutes = GitHubConnectionsRoutes(this)

    /** The `gitHubWebhooks` routes, as `api.gitHubWebhooks` in the web's client. */
    val gitHubWebhooks: GitHubWebhooksRoutes = GitHubWebhooksRoutes(this)

    /** The `modelProviders` routes, as `api.modelProviders` in the web's client. */
    val modelProviders: ModelProvidersRoutes = ModelProvidersRoutes(this)

    /** The `modelTrials` routes, as `api.modelTrials` in the web's client. */
    val modelTrials: ModelTrialsRoutes = ModelTrialsRoutes(this)

    /** The `notifications` routes, as `api.notifications` in the web's client. */
    val notifications: NotificationsRoutes = NotificationsRoutes(this)

    /** The `onboarding` routes, as `api.onboarding` in the web's client. */
    val onboarding: OnboardingRoutes = OnboardingRoutes(this)

    /** The `pods` routes, as `api.pods` in the web's client. */
    val pods: PodsRoutes = PodsRoutes(this)

    /** The `podSandbox` routes, as `api.podSandbox` in the web's client. */
    val podSandbox: PodSandboxRoutes = PodSandboxRoutes(this)

    /** The `referrals` routes, as `api.referrals` in the web's client. */
    val referrals: ReferralsRoutes = ReferralsRoutes(this)

    /** The `routines` routes, as `api.routines` in the web's client. */
    val routines: RoutinesRoutes = RoutinesRoutes(this)

    /** The `sandboxProviders` routes, as `api.sandboxProviders` in the web's client. */
    val sandboxProviders: SandboxProvidersRoutes = SandboxProvidersRoutes(this)

    /** The `searchProviders` routes, as `api.searchProviders` in the web's client. */
    val searchProviders: SearchProvidersRoutes = SearchProvidersRoutes(this)

    /** The `systemAgents` routes, as `api.systemAgents` in the web's client. */
    val systemAgents: SystemAgentsRoutes = SystemAgentsRoutes(this)

    /** The `threads` routes, as `api.threads` in the web's client. */
    val threads: ThreadsRoutes = ThreadsRoutes(this)

    /** The `toolApprovals` routes, as `api.toolApprovals` in the web's client. */
    val toolApprovals: ToolApprovalsRoutes = ToolApprovalsRoutes(this)

    /** The `usage` routes, as `api.usage` in the web's client. */
    val usage: UsageRoutes = UsageRoutes(this)

    /** The `workspaces` routes, as `api.workspaces` in the web's client. */
    val workspaces: WorkspacesRoutes = WorkspacesRoutes(this)

    suspend fun health(): HealthResponse {
        return this.call("GET", "health")
    }

    suspend fun me(): Me {
        return this.call("GET", "me")
    }

    suspend fun workspaceAccess(workspace: String): WorkspaceAccessResponse {
        return this.call("GET", "workspaces/${pathSegment(workspace)}/me")
    }

    @Serializable
    data class WorkspaceAccessResponse(
        val role: WorkspaceRole? = null,
        val permissions: WorkspacePermissions,
    )
}

/** The `agents` routes, as `api.agents` in the web's client. */
class AgentsRoutes internal constructor(private val client: ApiCaller) {
    suspend fun list(workspace: String): List<Agent> {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/agents")
    }

    suspend fun create(podId: String, name: String, handle: String? = null, description: Omittable<String?> = Omittable.Omitted, color: AgentColor? = null, face: AgentFace? = null, shape: AgentShape? = null, model: String, prompt: String? = null, disabledTools: List<String>? = null, usesSandbox: Boolean? = null, naturalBrowsing: Boolean? = null): Agent {
        return client.call("POST", "pods/${pathSegment(podId)}/agents", body = client.jsonBody(NewAgentInPod(name = name, handle = handle, description = description, color = color, face = face, shape = shape, model = model, prompt = prompt, disabledTools = disabledTools, usesSandbox = usesSandbox, naturalBrowsing = naturalBrowsing)))
    }

    suspend fun get(agentId: String): Agent {
        return client.call("GET", "agents/${pathSegment(agentId)}")
    }

    suspend fun update(agentId: String, name: String? = null, handle: Omittable<String?> = Omittable.Omitted, description: Omittable<String?> = Omittable.Omitted, color: Omittable<AgentColor?> = Omittable.Omitted, face: Omittable<AgentFace?> = Omittable.Omitted, shape: Omittable<AgentShape?> = Omittable.Omitted, model: Omittable<String?> = Omittable.Omitted, prompt: Omittable<String?> = Omittable.Omitted, disabledTools: Omittable<List<String>?> = Omittable.Omitted, usesSandbox: Omittable<Boolean?> = Omittable.Omitted, naturalBrowsing: Omittable<Boolean?> = Omittable.Omitted): Agent {
        return client.call("PATCH", "agents/${pathSegment(agentId)}", body = client.jsonBody(AgentUpdate(name = name, handle = handle, description = description, color = color, face = face, shape = shape, model = model, prompt = prompt, disabledTools = disabledTools, usesSandbox = usesSandbox, naturalBrowsing = naturalBrowsing)))
    }

    suspend fun remove(agentId: String) {
        client.callForData("DELETE", "agents/${pathSegment(agentId)}")
    }
}

