/** The `chats` routes, as `api.chats` in the web's client. */
class ChatsRoutes internal constructor(private val client: ApiCaller) {
    suspend fun list(workspace: String, pod: String): ChatList {
        val query = QueryItems()
        query.add("pod", pod)
        return client.call("GET", "workspaces/${pathSegment(workspace)}/chats", query)
    }

    suspend fun podMarkers(workspace: String): PodChatMarkers {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/chats/pod-markers")
    }

    suspend fun activity(workspace: String): ActivityFeed {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/chats/activity")
    }

    suspend fun approvals(workspace: String): ApprovalInbox {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/chats/approvals")
    }

    suspend fun openBotChannel(workspace: String, podId: String, hostAgentId: String): BotChannel {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/bot-channels", body = client.jsonBody(OpenBotChannel(podId = podId, hostAgentId = hostAgentId)))
    }

    suspend fun openRoutineFeed(workspace: String, routineId: String): RoutineFeed {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/routines/${pathSegment(routineId)}/thread")
    }

    suspend fun openPodChat(workspace: String, podId: String): PodChat {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/pods/${pathSegment(podId)}/chat")
    }

    suspend fun startChat(podId: String, name: String): PodChat {
        return client.call("POST", "pods/${pathSegment(podId)}/chats", body = client.jsonBody(NewChat(name = name)))
    }

    suspend fun renameChat(conversationId: String, name: String) {
        client.callForData("PUT", "conversations/${pathSegment(conversationId)}/name", body = client.jsonBody(NewChat(name = name)))
    }

    suspend fun archiveChat(conversationId: String) {
        client.callForData("PUT", "conversations/${pathSegment(conversationId)}/archived")
    }

    suspend fun startThread(conversationId: String, id: String, message: String, attachments: List<String>? = null, hostAgentId: String? = null, replyTo: String? = null): StartedThread {
        return client.call("POST", "conversations/${pathSegment(conversationId)}/threads", body = client.jsonBody(NewThread(id = id, message = message, attachments = attachments, hostAgentId = hostAgentId, replyTo = replyTo)))
    }

    suspend fun threadFrom(messageId: String): ConversationThread {
        return client.call("POST", "messages/${pathSegment(messageId)}/thread")
    }

    suspend fun messages(conversationId: String, cursor: String? = null, limit: String? = null): ChatMessagesPage {
        val query = QueryItems()
        query.add("cursor", cursor)
        query.add("limit", limit)
        return client.call("GET", "conversations/${pathSegment(conversationId)}/messages", query)
    }

    suspend fun send(conversationId: String, id: String, message: String, attachments: List<String>? = null, replyTo: String? = null): Message {
        return client.call("POST", "conversations/${pathSegment(conversationId)}/messages", body = client.jsonBody(NewMessage(id = id, message = message, attachments = attachments, replyTo = replyTo)))
    }

    suspend fun history(conversationId: String, cursor: String? = null, limit: String? = null): ChatHistoryPage {
        val query = QueryItems()
        query.add("cursor", cursor)
        query.add("limit", limit)
        return client.call("GET", "conversations/${pathSegment(conversationId)}/history", query)
    }

    suspend fun markDone(conversationId: String) {
        client.callForData("PUT", "conversations/${pathSegment(conversationId)}/done")
    }

    suspend fun reopen(conversationId: String) {
        client.callForData("DELETE", "conversations/${pathSegment(conversationId)}/done")
    }

    suspend fun markRead(conversationId: String) {
        client.callForData("POST", "conversations/${pathSegment(conversationId)}/read")
    }

    suspend fun uploadFile(conversationId: String, name: String, type: String? = null, data: ByteArray): UploadedAttachment {
        val query = QueryItems()
        query.add("name", name)
        query.add("type", type)
        return client.call("POST", "conversations/${pathSegment(conversationId)}/files", query, body = ApiRequestBody.Bytes(data))
    }

    suspend fun removeFile(conversationId: String, fileId: String) {
        client.callForData("DELETE", "conversations/${pathSegment(conversationId)}/files/${pathSegment(fileId)}")
    }

    suspend fun file(conversationId: String, fileId: String): ByteArray {
        return client.callForData("GET", "conversations/${pathSegment(conversationId)}/files/${pathSegment(fileId)}")
    }
}

