/** The `notifications` routes, as `api.notifications` in the web's client. */
class NotificationsRoutes internal constructor(private val client: ApiCaller) {
    suspend fun settings(): NotificationSettings {
        return client.call("GET", "notifications")
    }

    suspend fun updatePreferences(level: NotificationLevel, pausedUntil: Instant? = null, quietHours: QuietHours? = null, turnFailures: Boolean, routineRuns: RoutineRunNotifications): NotificationSettings {
        return client.call("PUT", "notifications", body = client.jsonBody(NotificationPreferences(level = level, pausedUntil = pausedUntil, quietHours = quietHours, turnFailures = turnFailures, routineRuns = routineRuns)))
    }

    suspend fun setLevel(kind: NotificationPlaceKind, id: String, level: NotificationLevel? = null) {
        client.callForData("PUT", "notifications/${pathSegment(kind.rawValue)}/${pathSegment(id)}/level", body = client.jsonBody(NotificationLevelChoice(level = level)))
    }

    suspend fun mute(kind: NotificationPlaceKind, id: String, until: Instant? = null) {
        client.callForData("PUT", "notifications/${pathSegment(kind.rawValue)}/${pathSegment(id)}/mute", body = client.jsonBody(NotificationMute(until = until)))
    }

    suspend fun sendTest() {
        client.callForData("POST", "notifications/test")
    }

    suspend fun reportPresence(clientId: String, conversationId: String? = null, sequence: Long) {
        client.callForData("PUT", "notifications/presence", body = client.jsonBody(Presence(clientId = clientId, conversationId = conversationId, sequence = sequence)))
    }
}

