/** The `pods` routes, as `api.pods` in the web's client. */
class PodsRoutes internal constructor(private val client: ApiCaller) {
    suspend fun list(workspace: String): List<Pod> {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/pods")
    }

    suspend fun create(workspace: String, name: String, slug: String? = null, color: PodColor? = null): Pod {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/pods", body = client.jsonBody(NewPod(name = name, slug = slug, color = color)))
    }

    suspend fun ensurePersonal(workspace: String, model: String): Pod {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/personal-pod", body = client.jsonBody(EnsurePersonalBody(model = model)))
    }

    suspend fun update(podId: String, name: String? = null, slug: Omittable<String?> = Omittable.Omitted, color: Omittable<PodColor?> = Omittable.Omitted): Pod {
        return client.call("PATCH", "pods/${pathSegment(podId)}", body = client.jsonBody(PodUpdate(name = name, slug = slug, color = color)))
    }

    suspend fun remove(podId: String) {
        client.callForData("DELETE", "pods/${pathSegment(podId)}")
    }

    suspend fun listMembers(podId: String): List<PodMember> {
        return client.call("GET", "pods/${pathSegment(podId)}/members")
    }

    suspend fun addMember(podId: String, userId: String) {
        client.callForData("POST", "pods/${pathSegment(podId)}/members", body = client.jsonBody(NewPodMember(userId = userId)))
    }

    suspend fun removeMember(podId: String, userId: String) {
        client.callForData("DELETE", "pods/${pathSegment(podId)}/members/${pathSegment(userId)}")
    }

    suspend fun leave(podId: String) {
        client.callForData("DELETE", "pods/${pathSegment(podId)}/membership")
    }

    @Serializable
    data class EnsurePersonalBody(
        val model: String,
    )
}

