/** The `routines` routes, as `api.routines` in the web's client. */
class RoutinesRoutes internal constructor(private val client: ApiCaller) {
    suspend fun listInWorkspace(workspace: String): WorkspaceRoutineList {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/routines")
    }

    suspend fun list(agentId: String): List<Routine> {
        return client.call("GET", "agents/${pathSegment(agentId)}/routines")
    }

    suspend fun create(agentId: String, name: String, instructions: String, state: RoutineState? = null, results: RoutineResults? = null, chatId: Omittable<String?> = Omittable.Omitted, triggers: List<RoutineTriggerInput>): RoutineWriteResult {
        return client.call("POST", "agents/${pathSegment(agentId)}/routines", body = client.jsonBody(NewRoutine(name = name, instructions = instructions, state = state, results = results, chatId = chatId, triggers = triggers)))
    }

    suspend fun previewSchedule(agentId: String, schedule: RoutineSchedule, timezone: String): RoutineScheduleOccurrences {
        return client.call("POST", "agents/${pathSegment(agentId)}/routines/schedule-preview", body = client.jsonBody(RoutineSchedulePreview(schedule = schedule, timezone = timezone)))
    }

    suspend fun get(agentId: String, routineId: String): Routine {
        return client.call("GET", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}")
    }

    suspend fun update(agentId: String, routineId: String, name: String? = null, instructions: String? = null, state: RoutineState? = null, results: RoutineResults? = null, chatId: Omittable<String?> = Omittable.Omitted): RoutineWriteResult {
        return client.call("PATCH", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}", body = client.jsonBody(RoutineUpdate(name = name, instructions = instructions, state = state, results = results, chatId = chatId)))
    }

    suspend fun remove(agentId: String, routineId: String) {
        client.callForData("DELETE", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}")
    }

    suspend fun run(agentId: String, routineId: String, requestId: String): AcceptedRoutineExecution {
        return client.call("POST", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/run", body = client.jsonBody(ManualRoutineRun(requestId = requestId)))
    }

    suspend fun addTrigger(agentId: String, routineId: String, body: RoutineTriggerInput): RoutineWriteResult {
        return client.call("POST", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/triggers", body = client.jsonBody(body))
    }

    suspend fun updateTrigger(agentId: String, routineId: String, triggerId: String, body: RoutineTriggerInput): RoutineWriteResult {
        return client.call("PUT", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/triggers/${pathSegment(triggerId)}", body = client.jsonBody(body))
    }

    suspend fun removeTrigger(agentId: String, routineId: String, triggerId: String): Routine {
        return client.call("DELETE", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/triggers/${pathSegment(triggerId)}")
    }

    suspend fun getSecret(agentId: String, routineId: String, triggerId: String): RoutineCurrentSecret {
        return client.call("GET", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/triggers/${pathSegment(triggerId)}/secret")
    }

    suspend fun rotateSecret(agentId: String, routineId: String, triggerId: String, secret: Omittable<String?> = Omittable.Omitted): RoutineSecret {
        return client.call("POST", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/triggers/${pathSegment(triggerId)}/secret", body = client.jsonBody(RoutineSecretReplacement(secret = secret)))
    }

    suspend fun executions(agentId: String, routineId: String, cursor: String? = null, limit: String? = null): RoutineExecutionPage {
        val query = QueryItems()
        query.add("cursor", cursor)
        query.add("limit", limit)
        return client.call("GET", "agents/${pathSegment(agentId)}/routines/${pathSegment(routineId)}/executions", query)
    }

    suspend fun webhook(triggerId: String, body: JsonElement): WebhookResponse {
        return client.call("POST", "hooks/triggers/${pathSegment(triggerId)}", body = client.jsonBody(body))
    }

    suspend fun routineWebhook(routineId: String, body: JsonElement): RoutineWebhookResponse {
        return client.call("POST", "hooks/routines/${pathSegment(routineId)}", body = client.jsonBody(body))
    }

    @Serializable(with = WebhookResponse.Serializer::class)
    sealed interface WebhookResponse {
        data class IgnoredRoutineWebhook(val value: ai.sugabots.api.IgnoredRoutineWebhook) : WebhookResponse

        data class RoutineWebhookChallenge(val value: ai.sugabots.api.RoutineWebhookChallenge) : WebhookResponse

        object Serializer : JsonUnionSerializer<WebhookResponse>("ai.sugabots.api.RoutinesRoutes.WebhookResponse") {
            override fun decode(element: JsonElement, json: Json): WebhookResponse {
                json.decodeOrNull<ai.sugabots.api.IgnoredRoutineWebhook>(element)?.let { return IgnoredRoutineWebhook(it) }
                json.decodeOrNull<ai.sugabots.api.RoutineWebhookChallenge>(element)?.let { return RoutineWebhookChallenge(it) }
                throw SerializationException("None of WebhookResponse's kinds.")
            }

            override fun encode(value: WebhookResponse, json: Json): JsonElement =
                when (value) {
                    is IgnoredRoutineWebhook -> json.encodeToJsonElement<ai.sugabots.api.IgnoredRoutineWebhook>(value.value)
                    is RoutineWebhookChallenge -> json.encodeToJsonElement<ai.sugabots.api.RoutineWebhookChallenge>(value.value)
                }
        }
    }

    @Serializable(with = RoutineWebhookResponse.Serializer::class)
    sealed interface RoutineWebhookResponse {
        data class IgnoredRoutineWebhook(val value: ai.sugabots.api.IgnoredRoutineWebhook) : RoutineWebhookResponse

        data class RoutineWebhookChallenge(val value: ai.sugabots.api.RoutineWebhookChallenge) : RoutineWebhookResponse

        object Serializer : JsonUnionSerializer<RoutineWebhookResponse>("ai.sugabots.api.RoutinesRoutes.RoutineWebhookResponse") {
            override fun decode(element: JsonElement, json: Json): RoutineWebhookResponse {
                json.decodeOrNull<ai.sugabots.api.IgnoredRoutineWebhook>(element)?.let { return IgnoredRoutineWebhook(it) }
                json.decodeOrNull<ai.sugabots.api.RoutineWebhookChallenge>(element)?.let { return RoutineWebhookChallenge(it) }
                throw SerializationException("None of RoutineWebhookResponse's kinds.")
            }

            override fun encode(value: RoutineWebhookResponse, json: Json): JsonElement =
                when (value) {
                    is IgnoredRoutineWebhook -> json.encodeToJsonElement<ai.sugabots.api.IgnoredRoutineWebhook>(value.value)
                    is RoutineWebhookChallenge -> json.encodeToJsonElement<ai.sugabots.api.RoutineWebhookChallenge>(value.value)
                }
        }
    }
}

