/** The `workspaces` routes, as `api.workspaces` in the web's client. */
class WorkspacesRoutes internal constructor(private val client: ApiCaller) {
    suspend fun list(): List<Workspace> {
        return client.call("GET", "workspaces")
    }

    suspend fun create(name: String, slug: String, timeZone: String? = null): Workspace {
        return client.call("POST", "workspaces", body = client.jsonBody(NewWorkspace(name = name, slug = slug, timeZone = timeZone)))
    }

    suspend fun update(workspace: String, name: String, slug: String): Workspace {
        return client.call("PATCH", "workspaces/${pathSegment(workspace)}", body = client.jsonBody(WorkspaceDetails(name = name, slug = slug)))
    }

    suspend fun delete(workspace: String) {
        client.callForData("DELETE", "workspaces/${pathSegment(workspace)}")
    }

    suspend fun timeZone(workspace: String): WorkspaceTimeZone {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/time-zone")
    }

    suspend fun changeTimeZone(workspace: String, timeZone: String) {
        client.callForData("PUT", "workspaces/${pathSegment(workspace)}/time-zone", body = client.jsonBody(WorkspaceTimeZoneChange(timeZone = timeZone)))
    }

    suspend fun members(workspace: String): List<WorkspaceMember> {
        return client.call("GET", "workspaces/${pathSegment(workspace)}/members")
    }

    suspend fun updateMember(workspace: String, memberId: String, role: AssignableWorkspaceRole) {
        client.callForData("PATCH", "workspaces/${pathSegment(workspace)}/members/${pathSegment(memberId)}", body = client.jsonBody(WorkspaceMemberUpdate(role = role)))
    }

    suspend fun removeMember(workspace: String, memberId: String) {
        client.callForData("DELETE", "workspaces/${pathSegment(workspace)}/members/${pathSegment(memberId)}")
    }

    suspend fun transferOwnership(workspace: String, memberId: String) {
        client.callForData("PUT", "workspaces/${pathSegment(workspace)}/owner", body = client.jsonBody(OwnershipTransfer(memberId = memberId)))
    }

    suspend fun leave(workspace: String) {
        client.callForData("POST", "workspaces/${pathSegment(workspace)}/leave")
    }

    suspend fun invitations(workspace: String): List<WorkspaceInvitation> {
