    }

    suspend fun invite(workspace: String, email: String, role: AssignableWorkspaceRole, resend: Boolean? = null): WorkspaceInvitation {
        return client.call("POST", "workspaces/${pathSegment(workspace)}/invitations", body = client.jsonBody(NewWorkspaceInvitation(email = email, role = role, resend = resend)))
    }

    suspend fun cancelInvitation(invitationId: String) {
        client.callForData("DELETE", "invitations/${pathSegment(invitationId)}")
    }

    suspend fun invitation(invitationId: String): InvitationPreview {
        return client.call("GET", "invitations/${pathSegment(invitationId)}")
    }

    suspend fun acceptInvitation(invitationId: String): AcceptedInvitation {
        return client.call("POST", "invitations/${pathSegment(invitationId)}/accept")
    }
}
